      pack_into(8, 'q>', v)
    end

    def write_Bool(v)
      pack_into(1, 'c', v ? 1 : 0)
    end

    def write_String(v)
      v = TrafilaturaUniffi.uniffi_utf8(v)
      pack_into 4, 'l>', v.bytes.size
      write v
    end

