      write_Optionalstring(v.original_url)
      write_Optionalstring(v.target_language)
      write_Bool(v.enable_fallback)
      write_TypeExtractionFocus(v.focus)
      write_Bool(v.exclude_comments)
      write_Bool(v.exclude_tables)
      write_Bool(v.include_images)
      write_Bool(v.include_links)
      write_Bool(v.deduplicate)
      write_Bool(v.require_essential_metadata)
      write_Optionali64(v.max_tree_size)
      write_Optionalstring(v.prune_selector)
      write_TypeHtmlDateMode(v.html_date_mode)
      write_Optionalstring(v.html_date_override)
