      write_String(v.author)
      write_String(v.url)
      write_String(v.hostname)
      write_String(v.description)
      write_String(v.sitename)
      write_Optionalstring(v.date)
      write_Sequencestring(v.categories)
      write_Sequencestring(v.tags)
      write_String(v.id)
      write_String(v.fingerprint)
      write_String(v.license)
      write_String(v.language)
